using System;using System.Linq;using System.Text;using System.Drawing;using System.Diagnostics;using System.Windows.Forms;using System.Collections.Generic;using System.Runtime.InteropServices;
sealed class LiveApp {internal IntPtr Handle;internal string Title,App;public override string ToString(){return Title+" · "+App;}}
static class LiveWindows {
 [DllImport("user32.dll")]static extern IntPtr GetWindowLongPtr(IntPtr h,int key);
 delegate bool Callback(IntPtr h,IntPtr p);[DllImport("user32.dll")]static extern bool EnumWindows(Callback f,IntPtr p);[DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr h);[DllImport("user32.dll")]static extern IntPtr GetWindow(IntPtr h,int n);[DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr h,out uint pid);[DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr h,StringBuilder s,int n);[DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetClassName(IntPtr h,StringBuilder s,int n);[DllImport("dwmapi.dll")]static extern int DwmGetWindowAttribute(IntPtr h,int key,out int value,int size);[DllImport("user32.dll")]static extern bool ShowWindow(IntPtr h,int n);[DllImport("user32.dll")]static extern bool IsIconic(IntPtr h);[DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr h);[DllImport("user32.dll")]static extern bool GetWindowRect(IntPtr h,out Rect r);[StructLayout(LayoutKind.Sequential)]struct Rect{internal int L,T,R,B;}
 internal static List<LiveApp> List(){var result=new List<LiveApp>();EnumWindows((h,p)=>{try{if(!IsWindowVisible(h)||GetWindow(h,4)!=IntPtr.Zero||(GetWindowLongPtr(h,-20).ToInt64()&0x80)!=0)return true;var title=new StringBuilder(500);GetWindowText(h,title,500);if(title.Length==0)return true;var cls=new StringBuilder(100);GetClassName(h,cls,100);if(new[]{"Progman","WorkerW","Shell_TrayWnd","Shell_SecondaryTrayWnd"}.Contains(cls.ToString()))return true;int cloaked;if(DwmGetWindowAttribute(h,14,out cloaked,4)==0&&cloaked!=0)return true;uint pid;GetWindowThreadProcessId(h,out pid);using(var proc=Process.GetProcessById((int)pid)){string app=proc.ProcessName;if(new[]{"Jago-Companion","Jago-Recorder","Jago-Capture","Jago-Preview","Jago-Update"}.Contains(app,StringComparer.OrdinalIgnoreCase))return true;result.Add(new LiveApp{Handle=h,Title=title.ToString(),App=app});}}catch{}return true;},IntPtr.Zero);return result.OrderBy(x=>x.Title,StringComparer.CurrentCultureIgnoreCase).ToList();}
 internal static Rectangle BringForward(IntPtr h){if(IsIconic(h))ShowWindow(h,9);SetForegroundWindow(h);Rect r;if(!GetWindowRect(h,out r))throw new Exception("That application closed. Refresh the app list and choose again.");return Rectangle.FromLTRB(r.L,r.T,r.R,r.B);}
}
sealed class LiveAppPicker:ThemeComboBox {internal LiveAppPicker(){DropDownStyle=ComboBoxStyle.DropDownList;DropDownWidth=600;Width=370;RefreshApps();DropDown+=(s,e)=>RefreshApps();}internal void RefreshApps(){IntPtr selected=SelectedItem is LiveApp?((LiveApp)SelectedItem).Handle:IntPtr.Zero;Items.Clear();foreach(var app in LiveWindows.List())Items.Add(app);SelectedItem=Items.Cast<LiveApp>().FirstOrDefault(x=>x.Handle==selected);if(SelectedIndex<0&&Items.Count>0)SelectedIndex=0;}internal IntPtr Chosen{get{return SelectedItem is LiveApp?((LiveApp)SelectedItem).Handle:IntPtr.Zero;}}}
